      inputsKey: inputsKeyOf(withoutIn),
      grafts: d.key === 'grafts' ? specs : [],
      startMoney: d.key === 'grafts' ? (started ? 0 : startMoney) : null,
      ...(setSwitch ? { setSwitch } : {}),
